def abort(msg):
    sys.exit(f"ABORT: {msg}. No files were written.")
REPLACE = {'frontend/src/App.jsx': {'before': '3923db45974187ef8fc507e7611cd0bcaad77790390946bf87c2b42823ebc16a', 'after': 'import { Suspense, lazy, useCallback, useEffect, useState } from \'react\';\nimport \'./dashboard.css\';\nimport \'./shell.css\';\nimport { api } from \'./api\';\nimport { useCase } from \'./useCase\';\nimport CaseSwitcher from \'./CaseSwitcher\';\nimport Overview from \'./Overview\';\nimport FamilyChips from \'./FamilyChips\';\nimport { attachStickyHeaders } from \'./stickyHeaders\';\nimport ThemeToggle from \'./ThemeToggle\';\nimport ConclusionGraph from \'./ConclusionGraph\';\nimport CaseFindingCard from \'./cards/CaseFindingCard\';\nimport RankingRevealCard from \'./cards/RankingRevealCard\';\nimport ObservedSceneCard from \'./cards/ObservedSceneCard\';\nimport HistoricalReplayCard from \'./cards/HistoricalReplayCard\';\nimport FragilityCard from \'./cards/FragilityCard\';\nimport ForecastCard from \'./cards/ForecastCard\';\nimport NextObservationCard from \'./cards/NextObservationCard\';\nimport CoverageCard from \'./cards/CoverageCard\';\nimport ProvenanceCard from \'./cards/ProvenanceCard\';\nimport AskSlickTraceCard from \'./cards/AskSlickTraceCard\';\n\n// loaded only when a tour starts, so driver.js is not in every page view\nconst Tour = lazy(() => import(\'./tour/Tour\'));\n\nexport default function App() {\n  const [incidents, setIncidents] = useState([]);\n  // Routes live in the URL hash, so Back and Forward work: #/overview (the\n  // default) or #/case/<id>. The last case opened stays loaded behind the\n  // overview, so returning to it is instant.\n  const parseRoute = () => {\n    const m = window.location.hash.match(/^#\\/case\\/([\\w-]+)/);\n    return m ? { view: \'case\', id: m[1] } : { view: \'overview\', id: null };\n  };\n  const [route, setRoute] = useState(parseRoute);\n  useEffect(() => {\n    const on = () => setRoute(parseRoute());\n    window.addEventListener(\'hashchange\', on);\n    return () => window.removeEventListener(\'hashchange\', on);\n  }, []);\n  const [lastCase, setLastCase] = useState(route.id ?? \'case_0001\');\n  if (route.id && route.id !== lastCase) setLastCase(route.id);\n  const incidentId = route.id ?? lastCase;\n  const openCase = useCallback((id) => { window.location.hash = `#/case/${id}`; }, []);\n  const openOverview = useCallback(() => { window.location.hash = \'#/overview\'; }, []);\n  // family filter for the overview grid; the sidebar always lists every case\n  const [family, setFamily] = useState(\'all\');\n  const { case: c, report, tracks, error } = useCase(incidentId);\n\n  useEffect(() => {\n    api.listIncidents().then(setIncidents).catch(() => setIncidents([]));\n  }, []);\n\n\n  const [touring, setTouring] = useState(false);\n\n  // Cross-fade between cases: the last fully loaded case stays on screen (dimmed)\n  // until the next has loaded, then fades in - rather than blanking and\n  // reloading. Updated during render, the standard pattern for derived state.\n  const [shown, setShown] = useState(null);\n  if (c && (shown?.c !== c || shown?.report !== report || shown?.tracks !== tracks)) {\n    setShown({ id: incidentId, c, report, tracks });\n  }\n  const vid = shown?.id;\n  const vc = shown?.c;\n  const leaving = !!shown && shown.id !== incidentId;\n  const meta = vc?.meta;\n\n  // scroll-edge effect on the pinned card headers; the column remounts per case\n  useEffect(() => attachStickyHeaders(document.querySelector(\'.finder-features\')), [vid, route.view]);\n\n  return (\n    <div className="app-shell">\n      <header className="topbar">\n        <div className="wordmark">\n          <svg className="wordmark-mark" viewBox="0 0 18 18" aria-hidden="true">\n            <rect width="18" height="18" rx="5" fill="var(--accent)" />\n            <path d="M9 3.6s-3.1 3.9-3.1 5.9a3.1 3.1 0 0 0 6.2 0C12.1 7.5 9 3.6 9 3.6Z" fill="#fff" />\n            <path d="M3.8 14c1.2-.9 2.3-.9 3.5 0s2.3.9 3.5 0 2.3-.9 3.4 0" stroke="#fff"\n                  strokeWidth="1.2" fill="none" strokeLinecap="round" opacity=".85" />\n          </svg>\n          Slick Trace<span className="wordmark-sub">Source attribution</span>\n        </div>\n        <div className="topbar-trailing">\n          {meta && route.view === \'case\' && (\n            <div className="topbar-meta">\n              <span className="tag tag-teal">{meta.case_state.replace(\'_\', \' \')}</span>\n              {meta.provenance.status === \'synthetic\' && <span className="tag tag-amber">synthetic case</span>}\n            </div>\n          )}\n          <button type="button" className={`tour-btn${touring ? \' is-on\' : \'\'}`} onClick={() => setTouring((t) => !t)}>\n            {touring ? \'Exit Tour\' : \'Start Tour\'}\n          </button>\n          <ThemeToggle />\n        </div>\n      </header>\n\n      {error && <div className="error-banner">Failed to load incident data: {error}</div>}\n      {touring && incidents.length > 0 && (\n        <Suspense fallback={null}>\n          <Tour incidents={incidents} api={api} selectCase={openCase} onExit={() => setTouring(false)} />\n        </Suspense>\n      )}\n\n      <div className="finder-layout">\n        <aside className="finder-sidebar">\n          <button type="button" className={`nav-overview${route.view === \'overview\' ? \' is-active\' : \'\'}`} onClick={openOverview}>\n            <svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2 2h5v5H2zM9 2h5v5H9zM2 9h5v5H2zM9 9h5v5H9z" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round" /></svg>\n            Overview\n          </button>\n          <CaseSwitcher incidents={incidents} active={route.view === \'case\' ? incidentId : null} onSelect={openCase} />\n        </aside>\n\n        {route.view === \'overview\' ? (\n          <Overview api={api} onOpen={openCase} family={family}\n                    chips={<FamilyChips incidents={incidents} value={family} onChange={setFamily} className="in-overview" />} />\n        ) : (\n        <div className={`finder-content${leaving ? \' is-leaving\' : \'\'}`} data-case={vid}>\n          {/* Evidence column, in the order a reviewer needs it: finding first. */}\n          <div className="finder-features" key={vid}>\n            {vc && (\n              <>\n                <CaseFindingCard attribution={vc.attribution} baseline={vc.baseline} vessels={vc.vessels} />\n                <RankingRevealCard attribution={vc.attribution} baseline={vc.baseline} vessels={vc.vessels} />\n                <ObservedSceneCard meta={meta} slick={vc.slick} sceneUrl={api.sceneUrl(vid)}\n                                   nVessels={vc.vessels.length} />\n                <HistoricalReplayCard incidentId={vid} api={api} c={vc} tracks={shown.tracks} />\n                <FragilityCard fragility={vc.fragility} />\n                <ForecastCard forecast={vc.forecast} />\n                <CoverageCard coverage={vc.coverage} />\n                <ProvenanceCard meta={meta} report={shown.report} />\n                {/* the case closes on what to check next */}\n                <NextObservationCard nextObs={vc.next_observation} closing />\n              </>\n            )}\n          </div>\n\n          <div className="finder-details" key={`d-${vid}`}>\n            {meta && (\n              <div className="report-buttons">\n                <a className="report-button" href={api.reportUrl(vid)} target="_blank" rel="noreferrer">\n                  Investigation Report\n                </a>\n                <a className="report-button" href={api.dossierUrl(vid)} target="_blank" rel="noreferrer">\n                  Dossier (PDF)\n                </a>\n              </div>\n            )}\n            {vc && (\n              <ConclusionGraph key={vid} attribution={vc.attribution} naive={vc.baseline}\n                               report={shown.report} detection={vc.slick} fragility={vc.fragility} />\n            )}\n            {vid && <AskSlickTraceCard key={`ask-${vid}`} incidentId={vid} api={api} />}\n          </div>\n        </div>\n        )}\n      </div>\n    </div>\n  );\n}\n'}, 'frontend/src/cards/NextObservationCard.jsx': {'before': 'a2534d665f311d0767941a505298e3f48607f39eb3ce9c871ea044a9e71251be', 'after': 'import { Badge, Card, EmptyState, Stat, StatGrid } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * Next observation: which future image would best separate the two leading\n * explanations. Reads the artifact\'s own recommended_window rather than\n * re-deriving it. Recommends evidence; it does not task a satellite.\n */\nconst hhmm = (s) => s.replace(\'T\', \' \').replace(\':00+00:00\', \' UTC\');\n\n// closing: shown as the last card of a case, framed as what to check next\nexport default function NextObservationCard({ nextObs, closing = false }) {\n  const frame = closing ? { eyebrow: \'What to check next\', className: \'is-closing\' } : {};\n  if (!nextObs) return null;\n  if (!nextObs.applicable) {\n    return (\n      <Card title="Next Observation" badge={<Badge>not applicable</Badge>} {...frame}>\n        <EmptyState>Not applicable for this incident: {nextObs.reason}</EmptyState>\n      </Card>\n    );\n  }\n  const rec = nextObs.recommended_window;\n  return (\n    <Card title="Next Observation" badge={<Badge tone="warning">advisory</Badge>} {...frame}\n          caption={`When one more image would best tell ${nextObs.hypothesis_a.vessel_key} and ${nextObs.hypothesis_b.vessel_key} apart.`}\n          footnote={`${rec.schedule_status}. ${nextObs.scope_note} ${nextObs.method_note}`}>\n      <StatGrid cols={3}>\n        <Stat label="Recommended window" value={`+${rec.horizon_hours} h`}\n              caption={`${hhmm(rec.valid_utc)}. ${C.recommended}`} />\n        <Stat label="Disagreement then" value={`${Math.round(rec.disagreement_score * 100)}%`}\n              caption={C.disagreement} />\n        <Stat label="Predicted overlap then" value={rec.predicted_overlap_iou.toFixed(3)}\n              caption={C.overlapIou} />\n      </StatGrid>\n      <div style={{ marginTop: \'var(--space-5)\' }}>\n        <div className="stat-label">Every tested window</div>\n        <div className="chip-steps" role="list" style={{ marginTop: \'var(--space-2)\' }}>\n          {nextObs.windows.map((w) => (\n            <span key={w.horizon_hours} role="listitem"\n                  className={`chip${w.horizon_hours === rec.horizon_hours ? \' is-active\' : \'\'}`}>\n              +{w.horizon_hours} h · {Math.round(w.disagreement_score * 100)}%\n              <span className="visually-hidden">{w.horizon_hours === rec.horizon_hours ? \' recommended\' : \'\'}</span>\n            </span>\n          ))}\n        </div>\n        <p className="stat-caption">Hours after the image, with the disagreement at each; the recommended one is filled.</p>\n      </div>\n    </Card>\n  );\n}\n'}, 'frontend/src/ui/primitives.jsx': {'before': '400fe2dbbd4030fb2b4e9cb92393571cc4c32d205365f2d930ab1605e51b574c', 'after': '/**\n * Generic building blocks every case card is composed from.\n *\n * Card: a section in the shell\'s hairline style, with title, badge, an\n * always-visible caption and a footnote. Stat: a value with its plain\n * caption underneath. BarList: ranked horizontal bars for either direction\n * of "better", with an optional gate marker. None of these compute anything\n * beyond scaling a bar to its row.\n */\n\nimport \'./ui.css\';\n\nexport function Card({ title, badge, caption, footnote, eyebrow, className = \'\', children }) {\n  return (\n    <section className={`panel card ${className}`.trim()}>\n      <div className="panel-head">\n        {/* the eyebrow sits inside the header, above the title: the header is pulled\n            up by a negative margin, so a line placed above it would be overlapped */}\n        {eyebrow ? <div className="panel-title"><div className="panel-eyebrow">{eyebrow}</div><h2>{title}</h2></div> : <h2>{title}</h2>}\n        {badge}\n      </div>\n      {caption && <p className="card-caption">{caption}</p>}\n      {children}\n      {footnote && <p className="card-foot">{footnote}</p>}\n    </section>\n  );\n}\n\nconst TONE = { neutral: \'tag\', accent: \'tag tag-teal\', warning: \'tag tag-amber\' };\n\nexport function Badge({ tone = \'neutral\', children }) {\n  return <span className={TONE[tone] ?? TONE.neutral}>{children}</span>;\n}\n\nexport function Stat({ label, value, caption, mono = false, text = false }) {\n  return (\n    <div className="stat">\n      <div className="stat-label">{label}</div>\n      <div className={`stat-value${mono ? \' is-mono\' : \'\'}${text ? \' is-text\' : \'\'}`}>{value}</div>\n      {caption && <div className="stat-caption">{caption}</div>}\n    </div>\n  );\n}\n\nexport function StatGrid({ cols = 3, children }) {\n  return <div className="stat-grid" style={{ \'--cols\': cols }}>{children}</div>;\n}\n\nexport function EmptyState({ children }) {\n  return <p className="card-empty">{children}</p>;\n}\n\n/**\n * rows: [{ key, value, sub }]. max defaults to the largest value. marker draws\n * a tick at a fixed value (a gate) in every row. highlightKey marks one row.\n */\nexport function BarList({ rows, max, marker, format, highlightKey, label, idPrefix }) {\n  const scale = max ?? Math.max(...rows.map((r) => r.value), 1e-9);\n  const pct = (v) => `${Math.max(0, Math.min(1, v / scale)) * 100}%`;\n  return (\n    <div className="barlist" role="table" aria-label={label}>\n      {rows.map((r, i) => (\n        <div role="row" key={r.key} id={idPrefix ? `${idPrefix}${r.key}` : undefined} style={{ \'--i\': i }}\n             className={`bar-row${r.key === highlightKey ? \' is-top\' : \'\'}`}>\n          <span role="cell" className="bar-key">{r.key}</span>\n          <span role="cell" className="bar-track" aria-hidden="true">\n            <span className="bar-fill" style={{ width: pct(r.value) }} />\n            {marker && <span className="bar-marker" style={{ left: pct(marker.value) }} />}\n          </span>\n          <span role="cell" className="bar-value">\n            {format(r.value)}\n            {r.sub && <span className="bar-sub">{r.sub}</span>}\n          </span>\n        </div>\n      ))}\n      {marker && (\n        <div className="bar-legend" aria-hidden="true">\n          <span className="bar-legend-tick" /> {marker.label}\n        </div>\n      )}\n    </div>\n  );\n}\n\nexport function CaptionList({ items }) {\n  return (\n    <dl className="caption-list">\n      {items.map(([term, text]) => (\n        <div key={term}>\n          <dt>{term}</dt>\n          <dd>{text}</dd>\n        </div>\n      ))}\n    </dl>\n  );\n}\n'}, 'frontend/src/ui/ui.css': {'before': 'c012ccc8868add2da224e4a8cfed05597533a8f5b437d22217a258340f37352a', 'after': '/* Generic card primitives, drawn with the design-system tokens. */\n\n.card-caption {\n  margin: -6px 0 var(--space-4);\n  max-width: 72ch;\n  font-size: var(--font-size-sm);\n  line-height: 1.45;\n  color: var(--label-2);\n}\n\n.card-foot {\n  margin: var(--space-4) 0 0;\n  max-width: 80ch;\n  font-size: var(--font-size-xs);\n  line-height: 1.45;\n  color: var(--label-2);\n}\n\n.card-empty {\n  margin: 0;\n  font-size: var(--font-size-sm);\n  color: var(--label-2);\n}\n\n/* --------------------------------------------------------------- stats */\n\n.stat-grid {\n  display: grid;\n  grid-template-columns: repeat(var(--cols, 3), minmax(0, 1fr));\n  gap: var(--space-4) var(--space-6);\n}\n\n.stat {\n  min-width: 0;\n}\n\n.stat-label {\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-semibold);\n  letter-spacing: 0.01em;\n  color: var(--label-2);\n}\n\n.stat-value {\n  margin-top: 2px;\n  font-size: var(--font-size-lg);\n  font-weight: var(--font-weight-medium);\n  line-height: 1.25;\n  letter-spacing: -0.01em;\n  color: var(--label-1);\n  font-variant-numeric: tabular-nums;\n  overflow-wrap: anywhere;\n}\n\n.stat-value.is-mono {\n  font-family: var(--font-mono);\n  font-size: var(--font-size-md);\n  letter-spacing: 0;\n}\n\n.stat-value.is-text {\n  font-size: var(--font-size-sm);\n  font-weight: var(--font-weight-normal);\n  line-height: 1.4;\n  letter-spacing: 0;\n}\n\n.stat-caption {\n  margin-top: 3px;\n  font-size: var(--font-size-xs);\n  line-height: 1.4;\n  color: var(--label-2);\n}\n\n/* ----------------------------------------------------------------- bars */\n\n.barlist {\n  display: grid;\n  gap: 6px;\n}\n\n.bar-row {\n  display: grid;\n  grid-template-columns: 92px minmax(0, 1fr) 118px;\n  align-items: center;\n  gap: var(--space-3);\n  padding: 3px 6px;\n  margin: 0 -6px;\n  border-radius: var(--radius-sm);\n  transition: background-color var(--dur-fast) ease;\n}\n\n.bar-row:hover {\n  background: var(--fill-hover);\n}\n\n.bar-key {\n  font-family: var(--font-mono);\n  font-size: var(--font-size-sm);\n  color: var(--label-strong);\n  font-variant-numeric: tabular-nums;\n}\n\n.bar-row.is-top .bar-key {\n  color: var(--label-1);\n  font-weight: var(--font-weight-semibold);\n}\n\n.bar-track {\n  position: relative;\n  height: 8px;\n  border-radius: 4px;\n  background: var(--surface-sunken);\n}\n\n.bar-fill {\n  position: absolute;\n  inset: 0 auto 0 0;\n  border-radius: 4px;\n  background: var(--label-3);\n  transform-origin: left center;\n  animation: bar-grow var(--dur-slow) var(--ease-spring) both;\n  animation-delay: calc(var(--i, 0) * 35ms);\n}\n\n.bar-row.is-top .bar-fill {\n  background: var(--accent);\n}\n\n.bar-marker {\n  position: absolute;\n  top: -3px;\n  bottom: -3px;\n  width: 1.5px;\n  margin-left: -0.75px;\n  border-radius: 1px;\n  background: var(--label-1);\n  opacity: 0.55;\n}\n\n.bar-value {\n  font-family: var(--font-mono);\n  font-size: var(--font-size-sm);\n  color: var(--label-1);\n  font-variant-numeric: tabular-nums;\n  white-space: nowrap;\n}\n\n.bar-sub {\n  margin-left: 8px;\n  color: var(--label-2);\n}\n\n.bar-legend {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  margin-top: 2px;\n  padding-left: calc(92px + var(--space-3));\n  font-size: var(--font-size-xs);\n  color: var(--label-2);\n}\n\n.bar-legend-tick {\n  display: inline-block;\n  width: 1.5px;\n  height: 11px;\n  background: var(--label-1);\n  opacity: 0.55;\n}\n\n@keyframes bar-grow {\n  from { transform: scaleX(0); }\n  to   { transform: scaleX(1); }\n}\n\n/* -------------------------------------------------------- caption lists */\n\n.caption-list {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: var(--space-2) var(--space-6);\n  margin: var(--space-4) 0 0;\n}\n\n.caption-list dt {\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-semibold);\n  color: var(--label-strong);\n}\n\n.caption-list dd {\n  margin: 1px 0 0;\n  font-size: var(--font-size-xs);\n  line-height: 1.4;\n  color: var(--label-2);\n}\n\n/* --------------------------------------------------------------- tables */\n\n.ui-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: var(--font-size-sm);\n}\n\n.ui-table th,\n.ui-table td {\n  padding: 9px 12px 9px 0;\n  text-align: left;\n  vertical-align: top;\n  border-bottom: 1px solid var(--separator);\n}\n\n.ui-table thead th {\n  padding-top: 0;\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-semibold);\n  color: var(--label-2);\n}\n\n.ui-table tbody th {\n  font-weight: var(--font-weight-medium);\n  color: var(--label-1);\n  white-space: nowrap;\n}\n\n.ui-table td {\n  color: var(--label-1);\n  font-variant-numeric: tabular-nums;\n}\n\n.ui-table .muted {\n  color: var(--label-2);\n}\n\n.ui-table .sub {\n  display: block;\n  margin-top: 2px;\n  font-size: var(--font-size-xs);\n  color: var(--label-2);\n}\n\n.ui-list {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.ui-list li + li {\n  margin-top: 3px;\n}\n\n/* --------------------------------------------------------------- finding */\n\n.finding {\n  border-top: 0;\n  margin-top: var(--space-6);\n  padding: var(--space-5) var(--space-6) var(--space-5);\n  border-radius: var(--radius-xl);\n  background: var(--surface-sunken);\n  box-shadow: inset 0 0 0 0.5px var(--separator);\n}\n\n.finder-features .finding > .panel-head {\n  position: static;\n  margin: 0 0 var(--space-2);\n  padding: 0;\n  background: none;\n  -webkit-backdrop-filter: none;\n  backdrop-filter: none;\n}\n\n.finding-line {\n  margin: 0 0 var(--space-4);\n  font-size: var(--font-size-md);\n  line-height: 1.4;\n  color: var(--label-1);\n}\n\n.finding-compare {\n  display: grid;\n  grid-template-columns: 1fr auto 1fr;\n  gap: var(--space-4);\n  align-items: start;\n}\n\n.finding-side-label {\n  margin-bottom: 4px;\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-semibold);\n  color: var(--label-2);\n}\n\n.finding-side.is-muted .stat-value {\n  color: var(--label-2);\n}\n\n.finding-arrow {\n  align-self: center;\n  color: var(--label-3);\n  font-size: 18px;\n}\n\n.finding-note {\n  margin: var(--space-4) 0 0;\n  padding-top: var(--space-3);\n  border-top: 1px solid var(--separator);\n  font-size: var(--font-size-xs);\n  line-height: 1.45;\n  color: var(--label-2);\n}\n\n/* ------------------------------------------------------------ controls */\n\n.ui-select {\n  height: 26px;\n  padding: 0 26px 0 10px;\n  border: 0;\n  border-radius: 7px;\n  background: var(--control-bg);\n  box-shadow: var(--shadow-control);\n  color: var(--label-1);\n  font-size: var(--font-size-sm);\n}\n\n.ui-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--space-2) var(--space-3);\n}\n\n.flip-box {\n  margin-top: var(--space-4);\n  padding: var(--space-3) var(--space-4);\n  border-radius: var(--radius-lg);\n  background: var(--status-orange-soft);\n}\n\n.flip-box .stat-value {\n  font-size: var(--font-size-md);\n}\n\n.chip-steps {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.chip {\n  display: inline-flex;\n  align-items: center;\n  height: 24px;\n  padding: 0 10px;\n  border: 0;\n  border-radius: 7px;\n  background: var(--surface-sunken);\n  color: var(--label-1);\n  font-family: var(--font-mono);\n  font-size: var(--font-size-xs);\n  font-variant-numeric: tabular-nums;\n  cursor: default;\n  transition: transform var(--dur-base) var(--ease-spring), background-color var(--dur-fast) ease;\n}\n\nbutton.chip:hover {\n  background: var(--fill-pressed);\n}\n\nbutton.chip:active {\n  transform: scale(0.95);\n  transition-duration: var(--dur-fast);\n}\n\n.chip.is-active {\n  background: var(--accent);\n  color: var(--on-accent);\n}\n\n.chip.is-flag {\n  box-shadow: inset 0 0 0 1px var(--status-orange);\n}\n\n@media (max-width: 900px) {\n  .stat-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .finding-compare { grid-template-columns: 1fr; }\n  .finding-arrow { display: none; }\n  .bar-row { grid-template-columns: 84px minmax(0, 1fr) 96px; }\n}\n\n/* a ranking row reached from the map flashes once */\n.bar-row.is-flash { animation: row-flash 1.8s var(--ease-out); border-radius: 6px; }\n@keyframes row-flash { 0%, 30% { background: rgba(10, 132, 255, 0.28); box-shadow: 0 0 0 1px rgba(10, 132, 255, 0.7); }\n                        100% { background: transparent; box-shadow: none; } }\n\n/* ------------------------------------------------ the abstain state (8d) */\n/* A deliberate outcome, not a weak result: an amber-rimmed surface, the\n   statement, and a meter showing every candidate\'s fit below the gate. */\n.finding.is-abstain {\n  background: linear-gradient(180deg, rgba(255, 159, 10, 0.07), rgba(255, 159, 10, 0.02)), var(--surface-sunken);\n  box-shadow: inset 0 0 0 1px rgba(255, 159, 10, 0.45), 0 0 28px rgba(255, 159, 10, 0.08);\n}\n.abstain-block { margin: 0 0 var(--space-4); }\n.abstain-head { display: flex; align-items: flex-start; gap: 12px; margin-bottom: var(--space-4); }\n.abstain-mark { flex: none; width: 30px; height: 30px; fill: none; stroke: var(--status-orange); stroke-width: 1.8; stroke-linecap: round; }\n.abstain-head strong { display: block; font-family: var(--font-display); font-size: var(--font-size-lg);\n                       font-weight: var(--font-weight-semibold); letter-spacing: -0.01em; color: var(--status-orange); }\n.abstain-head em { display: block; font-style: normal; font-size: var(--font-size-sm); color: var(--label-1); margin-top: 2px; }\n.finding.is-abstain .finding-line { color: var(--label-2); font-size: var(--font-size-sm); }\n\n.gate-meter { padding: 12px 14px 10px; border-radius: 10px; background: var(--surface-raised);\n              box-shadow: inset 0 0 0 0.5px var(--separator); }\n.gate-track { position: relative; height: 22px; margin: 4px 0 2px; border-radius: 6px;\n              background: linear-gradient(90deg, var(--fill-pressed), var(--fill-pressed)); }\n.gate-zone { position: absolute; top: 0; bottom: 0; right: 0; border-radius: 0 6px 6px 0;\n             background: repeating-linear-gradient(135deg, rgba(10, 132, 255, 0.14) 0 6px, rgba(10, 132, 255, 0.05) 6px 12px); }\n.gate-zone i { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); font-style: normal;\n               font-size: var(--font-size-xxs); color: var(--label-3); white-space: nowrap; }\n.gate-tick { position: absolute; top: -5px; bottom: -5px; width: 2px; margin-left: -1px; border-radius: 1px;\n             background: var(--status-orange); box-shadow: 0 0 8px rgba(255, 159, 10, 0.8); }\n.gate-dot { position: absolute; top: 50%; width: 10px; height: 10px; margin: -5px 0 0 -5px; border-radius: 50%;\n            background: var(--label-3); box-shadow: 0 0 0 1.5px var(--surface-raised); }\n.gate-dot.is-best { width: 13px; height: 13px; margin: -6.5px 0 0 -6.5px; background: var(--status-orange);\n                    box-shadow: 0 0 0 2px var(--surface-raised), 0 0 10px rgba(255, 159, 10, 0.7); }\n.gate-scale { position: relative; height: 16px; font-family: var(--font-mono); font-size: var(--font-size-xxs); color: var(--label-3); }\n.gate-scale span { position: absolute; transform: translateX(-50%); }\n.gate-scale span:first-child { transform: none; }\n.gate-scale span:last-child { transform: translateX(-100%); }\n.gate-scale .is-gate { color: var(--status-orange); font-weight: var(--font-weight-semibold); }\n.gate-caption { margin: 6px 0 0; font-size: var(--font-size-xs); color: var(--label-2); }\n\n/* a card\'s eyebrow, and the closing card of a case */\n.panel-title { display: flex; flex-direction: column; gap: 2px; }\n.panel-eyebrow { margin: 0; font-size: var(--font-size-xxs); font-weight: var(--font-weight-semibold);\n                 letter-spacing: 0.08em; text-transform: uppercase; color: var(--accent); }\n.finder-features .panel.is-closing { position: relative; margin-top: var(--space-6); }\n.finder-features .panel.is-closing::before {\n  content: ""; position: absolute; left: 0; right: 0; top: 0; height: 1px;\n  background: linear-gradient(90deg, transparent, rgba(10, 132, 255, 0.55), transparent);\n}\n'}}
CL_OLD = 'The filter chips now appear only above the overview grid; the sidebar lists every case.\n'
CL_NEW = 'The filter chips now appear only above the overview grid; the sidebar lists every case.\n\n**Next Observation closes each case.** It is now the last card, after Provenance, framed\n"What to check next"; it shows only its computed recommendation, unchanged.\n'
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 30 entry this appends after was not found")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 31: {len(writes)} files written, {skipped} already in place.")
